from collections import Counter

def task_func(file_pointer):
    """
    Reads from a given file pointer to a JSON file, evaluates strings that represent
    dictionaries to actual dictionaries, and counts the frequency of each key
    across all dictionary entries in the JSON data.

    Args:
        file_pointer: A file-like object containing JSON data.

    Returns:
        collections.Counter: A Counter object representing the frequency of each key 
                             found in the dictionaries.
    """
    # Load the JSON data from the file pointer
    # The data is expected to be a list of dicts or strings representing dicts
    try:
        data = json.load(file_pointer)
    except (json.JSONDecodeError, ValueError):
        return Counter()

    if not isinstance(data, list):
        return Counter()

    key_counts = Counter()

    for item in data:
        item_dict = None

        # If the item is a string, evaluate it to a dictionary
        if isinstance(item, str):
            try:
                # Use ast.literal_eval for safe evaluation of string literals
                evaluated = ast.literal_eval(item)
                if isinstance(evaluated, dict):
                    item_dict = evaluated
            except (ValueError, SyntaxError):
                # If evaluation fails or is not a dict, skip this item
                continue
        # If the item is already a dictionary
        elif isinstance(item, dict):
            item_dict = item

        # If we successfully identified/parsed a dictionary, count its keys
        if item_dict is not None:
            key_counts.update(item_dict.keys())

    return key_counts

